function drawSprite(c,p,x,y,scale=2,walk=false,frame=0,back=false){const colors={h:p.hair,s:p.skin,t:p.shirt,p:'#515d58',b:'#414e47',e:'#3e4640'};const female=p.id==='jiayee'||p.id==='greentea';spriteRows.forEach((row,ry)=>[...row].forEach((ch,rx)=>{if(ch==='.')return;let co=colors[ch];if(back&&(ch==='s'||ch==='e')&&ry<8)co=p.hair;if(female&&((rx===3||rx===11)&&ry>7&&ry<12))co=p.hair;if(p.id==='greentea'&&ry===5&&(rx===5||rx===6||rx===8||rx===9))co='#565b47';let dy=walk&&ry>15?(rx<8?frame:-frame):0;c.fillStyle=co;c.fillRect(Math.round(x+rx*scale),Math.round(y+ry*scale+dy),scale,scale)}));if(p.id==='jiayee'){c.fillStyle='#dfb3b4';c.fillRect(x+10*scale,y+2*scale,3*scale,2*scale)}if(p.id==='bobby'){c.fillStyle='#f0e6ce';c.fillRect(x+7*scale,y+10*scale,2*scale,3*scale)}}
function paintAvatars(){$$('canvas[data-person]').forEach(c=>{const p=person(c.dataset.person);if(!p)return;const ct=c.getContext('2d');ct.imageSmoothingEnabled=false;ct.fillStyle=p.light;ct.fillRect(0,0,c.width,c.height);const s=c.width/24;drawSprite(ct,p,4*s,2*s,s,false,0)})}
// Paths use the open aisles and doorways. A pause never advances the clock.
const nodes={j:[195,271],g:[390,271],m:[516,350],b:[192,478],b1:[253,478],b2:[253,466],b3:[350,466],md:[590,351],a:[295,279],c:[425,279],d:[590,279],e:[625,279],f:[625,364],g2:[625,450],h:[365,450],i:[425,365],review:[910,279],review2:[910,185],lounge:[705,450]};
const edges=[['j','a'],['g','c'],['a','c'],['c','d'],['d','e'],['d','md'],['md','m'],['e','f'],['f','g2'],['g2','h'],['h','i'],['i','c'],['h','b3'],['b3','b2'],['b2','b1'],['b1','b'],['e','review'],['review','review2'],['g2','lounge']];
function nearest(pt){return Object.keys(nodes).reduce((best,k)=>Math.hypot(pt[0]-nodes[k][0],pt[1]-nodes[k][1])<Math.hypot(pt[0]-nodes[best][0],pt[1]-nodes[best][1])?k:best,'j')}
function route(from,to){const start=nearest(from),end=to[0]>730&&to[0]<890&&to[1]<280?'review2':nearest(to),q=[[start]],seen=new Set([start]);while(q.length){const path=q.shift(),tail=path.at(-1);if(tail===end)return [...path.map(k=>nodes[k]),to];for(const [a,b]of edges){const n=a===tail?b:b===tail?a:null;if(n&&!seen.has(n)){seen.add(n);q.push([...path,n])}}}return[to]}
