people[0].home=[195,272];people[1].home=[390,272];people[2].home=[516,351];people[3].home=[192,478];
const actors=people.map((p,i)=>({id:p.id,x:p.home[0],y:p.home[1],mode:'work',zone:'inside',destination:'hq',travel:null,path:[],timer:15+i*13,step:i,bubble:0}));
function setMode(id,mode,auto=false){const a=actors.find(a=>a.id===id);if(!a)return;if(!auto){state.modes[id]=mode;save();log(id,mode==='auto'?'Automatic neighbourhood routine enabled.':places[mode]?`Heading to ${places[mode].name} for a little break.`:`Office location set to ${mode==='work'?'desk':mode==='break'?'coffee lounge':'review room'}.`);}const target=mode==='auto'?'work':mode;if(places[target]&&target!=='hq')sendOutside(a,target);else sendInside(a,['work','break','meeting'].includes(target)?target:'work');a.timer=target==='work'?35+Math.random()*25:24+Math.random()*20;a.bubble=3;updateStatus();}
for(const a of actors){const m=state.modes[a.id];if(m&&m!=='auto'&&(['work','break','meeting'].includes(m)||places[m]))setMode(a.id,m,true);}
function updateStatus(){for(const a of actors){const el=$(`[data-status="${a.id}"]`);if(el){el.textContent=a.path.length?'ON THE MOVE':places[a.mode]?'AT '+places[a.mode].short:a.mode==='break'?'ON BREAK':a.mode==='meeting'?'IN REVIEW':'AT DESK';el.classList.toggle('break',a.mode==='break'||!!places[a.mode]);}}const moving=actors.filter(a=>a.path.length).length,outside=actors.filter(a=>a.zone==='town').length;$('#office-status').textContent=paused?'A quiet moment. World animation paused.':moving?'A little work. A little walk. A little lepak.':outside?`${outside} teammate${outside===1?'':'s'} out in the neighbourhood. The good ideas can wait a minute.`:'The team is finding its rhythm upstairs.';}
function animate(t){if(!last)last=t;const dt=Math.min((t-last)/1000,.06);last=t;if(!paused){tick+=dt;for(const a of actors){a.bubble=Math.max(0,a.bubble-dt);if(a.path.length){const [tx,ty]=a.path[0],dx=tx-a.x,dy=ty-a.y,d=Math.hypot(dx,dy),speed=(a.zone==='town'?85:75)*dt;if(d<=speed||d<0.01){a.x=tx;a.y=ty;a.path.shift();if(!a.path.length&&a.travel)completeTravel(a);}else{a.x+=dx/d*speed;a.y+=dy/d*speed;}a.step+=dt*9;}else if(!state.modes[a.id]||state.modes[a.id]==='auto'){a.timer-=dt;if(a.timer<=0){const choices=['break','mamak','kopi','seven','plaza'];setMode(a.id,a.mode==='work'?choices[Math.floor(Math.random()*choices.length)]:'work',true);}}}}if(scene==='town')drawWorld();else drawRoom();for(const a of [...actors].filter(a=>a.zone===(scene==='town'?'town':'inside')).sort((a,b)=>a.y-b.y)){const p=person(a.id),walking=!!a.path.length,x=Math.round(a.x)-16,y=Math.round(a.y)-40;rect(x+1,y+37,32,7,'#77856440');drawSprite(ctx,p,x,y,2,walking,Math.sin(a.step)>0?2:-2,walking&&a.path[0][1]<a.y);if(!walking&&a.mode==='work'&&Math.floor(tick*2)%5===0){rect(x+2,y+22,3,4,p.skin);rect(x+26,y+23,3,4,p.skin);}const width=p.name.length*5+12;rect(a.x-width/2,a.y+10,width,14,'#fffcedef');text(p.name,a.x-width/2+6,a.y+20,'#66735d',8);if(!walking&&a.mode!=='work'&&a.mode!=='meeting'&&Math.sin(tick*2+a.step)>.3){text('♪',x+28,y-7,'#76916c',10);}if(a.bubble>0){rect(x+23,y-20,26,16,'#fbf7e4');rect(x+25,y-4,4,4,'#fbf7e4');text('...',x+28,y-9,'#96a280',9);}}if(scene==='inside'){if(night)rect(0,0,1000,565,'#35425630');if(!paused){const d=tick%6;if(d<3){const sy=365-d*3;rect(682,sy,2,3,'#ffffff77');rect(686,sy-5,2,3,'#ffffff55');}}}requestAnimationFrame(animate);}
cv.addEventListener('click',e=>{const r=cv.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*cv.width,y=(e.clientY-r.top)/r.height*cv.height;const a=[...actors].reverse().find(a=>a.zone===(scene==='town'?'town':'inside')&&Math.abs(a.x-x)<28&&y>a.y-48&&y<a.y+26);if(a){openPerson(a.id);return;}if(scene==='town'){for(const [id,p]of Object.entries(places)){const [hx,hy,hw,hh]=p.hit;if((x>=hx&&x<=hx+hw&&y>=hy&&y<=hy+hh)||(Math.abs(x-p.point[0])<32&&Math.abs(y-p.point[1])<22)){openPlace(id);break;}}}});
$('#pause').onclick=()=>{paused=!paused;updatePause();updateStatus();};function updatePause(){$('#pause').innerHTML=`${paused?'▶':'Ⅱ'} <span>${paused?'Resume':'Pause'}</span>`;$('#pause').setAttribute('aria-label',paused?'Resume employee animation':'Pause employee animation');$('#pause').setAttribute('aria-pressed',String(paused));}$('#day-mode').onclick=()=>{night=!night;state.night=night;save();updateDay();};function updateDay(){$('#day-mode').innerHTML=`${night?'☾':'☀'} <span>${night?'Evening':'Daylight'}</span>`;$('#day-mode').setAttribute('aria-label',night?'Switch to daylight':'Switch to evening lighting');}
